using System.Collections.ObjectModel;
using System.Windows.Input;
using VisualRelay.App.ViewModels.RunLogRows;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

public sealed class RunLogGroupingTests
{
    // ── helpers ──────────────────────────────────────────────────────────

    private static RelayEvent Heartbeat(int stageNumber, string tier, string message, DateTimeOffset? at = null) =>
        new(
            at ?? DateTimeOffset.UtcNow,
            "debug",
            "watchdog_heartbeat",
            "run-1",
            "/root",
            "task-1",
            stageNumber,
            tier,
            Data: new Dictionary<string, string> { ["message"] = message });

    private static RelayEvent StageStart(int stageNumber, string tier, DateTimeOffset? at = null) =>
        new(
            at ?? DateTimeOffset.UtcNow,
            "info",
            "stage_start",
            "run-1",
            "/root",
            "task-1",
            stageNumber,
            tier);

    private static RelayEvent Trace(int stageNumber, string tier, string title, string content, DateTimeOffset? at = null) =>
        new(
            at ?? DateTimeOffset.UtcNow,
            "info",
            "trace",
            "run-1",
            "/root",
            "task-1",
            stageNumber,
            tier,
            Data: new Dictionary<string, string> { ["title"] = title, ["content"] = content });

    // ── GroupEvents tests ────────────────────────────────────────────────

    [Fact]
    public void ConsecutiveMatchingHeartbeats_CollapseToSingleGroup()
    {
        var events = new[]
        {
            Heartbeat(7, "frontier", "silenceMs=1000 deadlineMs=62000"),
            Heartbeat(7, "frontier", "silenceMs=2000 deadlineMs=61000"),
            Heartbeat(7, "frontier", "silenceMs=3000 deadlineMs=60000"),
        };

        var rows = RunLogGrouper.GroupEvents(events);

        var group = Assert.Single(rows);
        Assert.True(group.IsGroup);
        Assert.Equal(3, group.Count);
        Assert.Equal("s7/frontier watchdog_heartbeat", group.DisplayLine);
        // Detail = newest member's detail (the first in newest-first order)
        Assert.Contains("silenceMs=1000", group.DetailLine);
        Assert.Contains("deadlineMs=62000", group.DetailLine);
    }

    [Fact]
    public void InterleavedNonHeartbeat_SplitsGroups()
    {
        var events = new[]
        {
            Heartbeat(7, "frontier", "msg3"),
            StageStart(7, "frontier"),
            Heartbeat(7, "frontier", "msg2"),
            Heartbeat(7, "frontier", "msg1"),
        };

        var rows = RunLogGrouper.GroupEvents(events);

        Assert.Equal(3, rows.Count);
        // First row: single heartbeat (before stage_start split)
        Assert.False(rows[0].IsGroup);
        Assert.Equal("watchdog_heartbeat", rows[0].Event.EventName);
        // Second row: stage_start (plain, non-heartbeat)
        Assert.False(rows[1].IsGroup);
        Assert.Equal("stage_start", rows[1].Event.EventName);
        // Third row: group of 2 heartbeats (after stage_start)
        Assert.True(rows[2].IsGroup);
        Assert.Equal(2, rows[2].Count);
        Assert.Equal("s7/frontier watchdog_heartbeat", rows[2].DisplayLine);
    }

    [Fact]
    public void TierChange_StartsNewGroup()
    {
        var events = new[]
        {
            Heartbeat(7, "frontier", "f3"),
            Heartbeat(7, "frontier", "f2"),
            Heartbeat(7, "balanced", "b2"),
            Heartbeat(7, "balanced", "b1"),
        };

        var rows = RunLogGrouper.GroupEvents(events);

        Assert.Equal(2, rows.Count);
        Assert.True(rows[0].IsGroup);
        Assert.Equal(2, rows[0].Count);
        Assert.Equal("s7/frontier watchdog_heartbeat", rows[0].DisplayLine);
        Assert.True(rows[1].IsGroup);
        Assert.Equal(2, rows[1].Count);
        Assert.Equal("s7/balanced watchdog_heartbeat", rows[1].DisplayLine);
    }

    [Fact]
    public void [ENCRYPTED:fastly]T-q3gxMOd5rLsN6or-A3P6fWOauMnZ-5()
    {
        var events = new[]
        {
            Heartbeat(6, "balanced", "s6b"),
            Heartbeat(7, "frontier", "s7f2"),
            Heartbeat(7, "frontier", "s7f1"),
        };

        var rows = RunLogGrouper.GroupEvents(events);

        Assert.Equal(2, rows.Count);
        // First row: single s6 heartbeat (no group because only one)
        Assert.False(rows[0].IsGroup);
        Assert.Equal("s6/balanced watchdog_heartbeat", rows[0].DisplayLine);
        // Second row: group of 2 s7 heartbeats
        Assert.True(rows[1].IsGroup);
        Assert.Equal(2, rows[1].Count);
        Assert.Equal("s7/frontier watchdog_heartbeat", rows[1].DisplayLine);
    }

    [Fact]
    public void SingleHeartbeat_RendersAsPlainRow()
    {
        var events = new[] { Heartbeat(7, "frontier", "msg") };

        var rows = RunLogGrouper.GroupEvents(events);

        var row = Assert.Single(rows);
        Assert.False(row.IsGroup);
        Assert.Equal("s7/frontier watchdog_heartbeat", row.DisplayLine);
        Assert.Equal(1, row.Count);
        Assert.Equal("watchdog_heartbeat", row.Event.EventName);
    }

    [Fact]
    public void NonHeartbeatEvents_AreByteIdenticalToToday()
    {
        var evt = StageStart(5, "balanced");

        var rows = RunLogGrouper.GroupEvents([evt]);

        var row = Assert.Single(rows);
        Assert.False(row.IsGroup);
        Assert.Same(evt, row.Event);
        Assert.Equal(evt.DisplayLine, row.DisplayLine);
        Assert.Equal(evt.DetailLine, row.DetailLine);
        Assert.Equal(evt.IsAttention, row.IsAttention);
    }

    [Fact]
    public void WarnEvent_NeverSwallowedIntoGroup()
    {
        // Heartbeats are always "debug" level. Verify that a "warn" event
        // cannot be absorbed — the grouping rule is keyed on EventName, not
        // Level, and warn/error events are never "watchdog_heartbeat".
        var evt = new RelayEvent(
            DateTimeOffset.UtcNow, "warn", "escalation", "run-1", "/root",
            "task-1", 7, "frontier");

        var rows = RunLogGrouper.GroupEvents([evt]);

        var row = Assert.Single(rows);
        Assert.False(row.IsGroup);
        Assert.Equal("escalation", row.Event.EventName);
        Assert.True(row.IsAttention);
    }

    [Fact]
    public void TwoHeartbeatsSeparatedByNonHeartbeat_AreTwoSeparateUngroupedRows()
    {
        var events = new RelayEvent[]
        {
            Heartbeat(7, "frontier", "second"),
            Trace(7, "frontier", "trace title", "trace content"),
            Heartbeat(7, "frontier", "first"),
        };

        var rows = RunLogGrouper.GroupEvents(events);

        Assert.Equal(3, rows.Count);
        // Each heartbeat is a single, ungrouped row because the trace splits them
        Assert.False(rows[0].IsGroup);
        Assert.Equal("watchdog_heartbeat", rows[0].Event.EventName);
        Assert.False(rows[1].IsGroup);
        Assert.Equal("trace", rows[1].Event.EventName);
        Assert.False(rows[2].IsGroup);
        Assert.Equal("watchdog_heartbeat", rows[2].Event.EventName);
    }

    [Fact]
    public void GroupEvents_EmptyInput_ReturnsEmpty()
    {
        var rows = RunLogGrouper.GroupEvents([]);
        Assert.Empty(rows);
    }

    [Fact]
    public void GroupEvents_SingleNonHeartbeat_ReturnsSingleRow()
    {
        var evt = StageStart(1, "cheap");
        var rows = RunLogGrouper.GroupEvents([evt]);
        var row = Assert.Single(rows);
        Assert.False(row.IsGroup);
        Assert.Same(evt, row.Event);
    }

    [Fact]
    public void GroupEvents_PreservesNewestFirstOrder()
    {
        var first = Heartbeat(7, "frontier", "first");
        var second = Heartbeat(7, "frontier", "second");
        var third = Heartbeat(7, "frontier", "third");

        var rows = RunLogGrouper.GroupEvents([third, second, first]);

        var group = Assert.Single(rows);
        Assert.Equal(3, group.Count);
        Assert.Same(third, group.Event); // newest = first in input
        Assert.Same(third, group.Members[0]);
        Assert.Same(second, group.Members[1]);
        Assert.Same(first, group.Members[2]);
    }

    // ── MergeNewest (live growth) tests ──────────────────────────────────

    [Fact]
    public void MergeNewest_IntoExistingGroup_IncrementsCountAndUpdatesDetail()
    {
        var rows = new ObservableCollection<IRunLogRow>();
        // Seed with a group of 2
        var group = HeartbeatGroupRow.Create(
            Heartbeat(7, "frontier", "silenceMs=60000 deadlineMs=120000"),
            Heartbeat(7, "frontier", "silenceMs=0 deadlineMs=60000"));
        rows.Add(group);
        Assert.Equal(2, group.Count);
        Assert.Contains("silenceMs=60000", group.DetailLine);

        // New heartbeat arrives
        var merged = RunLogGrouper.MergeNewest(
            rows,
            Heartbeat(7, "frontier", "silenceMs=2000 deadlineMs=62000"));

        Assert.True(merged);
        Assert.Equal(3, group.Count);
        // Row count stable — no new row added
        Assert.Single(rows);
        // Detail = newest (the just-merged event)
        Assert.Contains("silenceMs=2000", group.DetailLine);
        Assert.Contains("deadlineMs=62000", group.DetailLine);
    }

    [Fact]
    public void MergeNewest_IntoExistingGroup_PreservesExpandedState()
    {
        var rows = new ObservableCollection<IRunLogRow>();
        var group = HeartbeatGroupRow.Create(
            Heartbeat(7, "frontier", "msg2"),
            Heartbeat(7, "frontier", "msg1"));
        rows.Add(group);

        group.IsExpanded = true;
        Assert.True(group.IsExpanded);

        RunLogGrouper.MergeNewest(rows, Heartbeat(7, "frontier", "msg3"));

        Assert.True(group.IsExpanded,
            "Live count increment must not collapse an expanded group");
        Assert.Equal(3, group.Count);
    }

    [Fact]
    public void MergeNewest_DifferentTier_ReturnsFalse()
    {
        var rows = new ObservableCollection<IRunLogRow>();
        var group = HeartbeatGroupRow.Create(
            Heartbeat(7, "frontier", "msg2"),
            Heartbeat(7, "frontier", "msg1"));
        rows.Add(group);

        var merged = RunLogGrouper.MergeNewest(
            rows,
            Heartbeat(7, "balanced", "msg"));

        Assert.False(merged);
        Assert.Equal(2, group.Count);
    }

    [Fact]
    public void MergeNewest_DifferentStage_ReturnsFalse()
    {
        var rows = new ObservableCollection<IRunLogRow>();
        var group = HeartbeatGroupRow.Create(
            Heartbeat(7, "frontier", "msg2"),
            Heartbeat(7, "frontier", "msg1"));
        rows.Add(group);

        var merged = RunLogGrouper.MergeNewest(
            rows,
            Heartbeat(6, "frontier", "msg"));

        Assert.False(merged);
        Assert.Equal(2, group.Count);
    }

    [Fact]
    public void MergeNewest_NonHeartbeatEvent_ReturnsFalse()
    {
        var rows = new ObservableCollection<IRunLogRow>();
        var group = HeartbeatGroupRow.Create(
            Heartbeat(7, "frontier", "msg2"),
            Heartbeat(7, "frontier", "msg1"));
        rows.Add(group);

        var merged = RunLogGrouper.MergeNewest(
            rows,
            StageStart(7, "frontier"));

        Assert.False(merged);
        Assert.Equal(2, group.Count);
    }

    [Fact]
    public void MergeNewest_FirstRowIsSingleHeartbeat_PromotesToGroup()
    {
        var rows = new ObservableCollection<IRunLogRow>();
        var single = new SingleEventRow(Heartbeat(7, "frontier", "first"));
        rows.Add(single);

        var merged = RunLogGrouper.MergeNewest(
            rows,
            Heartbeat(7, "frontier", "second"));

        Assert.True(merged);
        // Should now be a group row, not a single
        Assert.Single(rows);
        Assert.True(rows[0].IsGroup);
        Assert.Equal(2, rows[0].Count);
    }

    [Fact]
    public void MergeNewest_FirstRowIsNonHeartbeat_ReturnsFalse()
    {
        var rows = new ObservableCollection<IRunLogRow>();
        rows.Add(new SingleEventRow(StageStart(7, "frontier")));

        var merged = RunLogGrouper.MergeNewest(
            rows,
            Heartbeat(7, "frontier", "msg"));

        Assert.False(merged);
    }

    [Fact]
    public void MergeNewest_EmptyCollection_ReturnsFalse()
    {
        var rows = new ObservableCollection<IRunLogRow>();

        var merged = RunLogGrouper.MergeNewest(
            rows,
            Heartbeat(7, "frontier", "msg"));

        Assert.False(merged);
    }

    // ── HeartbeatGroupRow expand/collapse ────────────────────────────────

    [Fact]
    public void ExpandCollapse_RoundTrips()
    {
        var group = HeartbeatGroupRow.Create(
            Heartbeat(7, "frontier", "msg3"),
            Heartbeat(7, "frontier", "msg2"),
            Heartbeat(7, "frontier", "msg1"));

        Assert.False(group.IsExpanded);
        Assert.Equal(3, group.Count);
        Assert.Equal(3, group.Members.Count);

        group.IsExpanded = true;
        Assert.True(group.IsExpanded);

        group.IsExpanded = false;
        Assert.False(group.IsExpanded);
    }

    [Fact]
    public void ExpandedGroup_MembersAreInNewestFirstOrder()
    {
        var h1 = Heartbeat(7, "frontier", "msg1");
        var h2 = Heartbeat(7, "frontier", "msg2");
        var h3 = Heartbeat(7, "frontier", "msg3");

        var group = HeartbeatGroupRow.Create(h3, h2, h1);

        Assert.Equal(3, group.Members.Count);
        Assert.Same(h3, group.Members[0]);
        Assert.Same(h2, group.Members[1]);
        Assert.Same(h1, group.Members[2]);
    }

    [Fact]
    public void ToggleExpandCommand_FlipsIsExpanded()
    {
        var group = HeartbeatGroupRow.Create(
            Heartbeat(7, "frontier", "msg2"),
            Heartbeat(7, "frontier", "msg1"));

        Assert.False(group.IsExpanded);
        Assert.NotNull(group.ToggleExpandCommand);

        group.ToggleExpandCommand.Execute(null);
        Assert.True(group.IsExpanded);

        group.ToggleExpandCommand.Execute(null);
        Assert.False(group.IsExpanded);
    }

    // ── HeartbeatGroupRow detail / display ───────────────────────────────

    [Fact]
    public void GroupRow_DisplayLine_IsSharedDisplayLine()
    {
        var group = HeartbeatGroupRow.Create(
            Heartbeat(7, "frontier", "msg3"),
            Heartbeat(7, "frontier", "msg2"));

        Assert.Equal("s7/frontier watchdog_heartbeat", group.DisplayLine);
    }

    [Fact]
    public void GroupRow_DetailLine_IsNewestMemberDetail()
    {
        var group = HeartbeatGroupRow.Create(
            Heartbeat(7, "frontier", "silenceMs=2000 deadlineMs=61000"),
            Heartbeat(7, "frontier", "silenceMs=1000 deadlineMs=62000"));

        // Newest is the first arg (silenceMs=2000)
        Assert.Contains("silenceMs=2000", group.DetailLine);
        Assert.DoesNotContain("silenceMs=1000", group.DetailLine);
    }

    [Fact]
    public void GroupRow_IsNeverAttention()
    {
        var group = HeartbeatGroupRow.Create(
            Heartbeat(7, "frontier", "msg2"),
            Heartbeat(7, "frontier", "msg1"));

        Assert.False(group.IsAttention);
    }

    [Fact]
    public void GroupRow_Create_WithSingleEvent_ReturnsSingleEventRow()
    {
        var row = HeartbeatGroupRow.Create(Heartbeat(7, "frontier", "msg"));

        Assert.False(row.IsGroup);
        Assert.IsType<SingleEventRow>(row);
        Assert.Equal(1, row.Count);
    }

    [Fact]
    public void GroupRow_Create_WithMultipleEvents_ReturnsHeartbeatGroupRow()
    {
        var row = HeartbeatGroupRow.Create(
            Heartbeat(7, "frontier", "msg2"),
            Heartbeat(7, "frontier", "msg1"));

        Assert.True(row.IsGroup);
        Assert.IsType<HeartbeatGroupRow>(row);
        Assert.Equal(2, row.Count);
    }

    // ── SingleEventRow ───────────────────────────────────────────────────

    [Fact]
    public void SingleEventRow_DelegatesToRelayEvent()
    {
        var evt = StageStart(5, "balanced");
        var row = new SingleEventRow(evt);

        Assert.False(row.IsGroup);
        Assert.Same(evt, row.Event);
        Assert.Equal(evt.DisplayLine, row.DisplayLine);
        Assert.Equal(evt.DetailLine, row.DetailLine);
        Assert.Equal(evt.IsAttention, row.IsAttention);
        Assert.Equal(1, row.Count);
        Assert.Single(row.Members);
        Assert.Same(evt, row.Members[0]);
    }

    [Fact]
    public void SingleEventRow_WarnEvent_IsAttention()
    {
        var evt = new RelayEvent(
            DateTimeOffset.UtcNow, "warn", "escalation", "run-1", "/root",
            "task-1", 7, "frontier");
        var row = new SingleEventRow(evt);

        Assert.True(row.IsAttention);
    }

    // ── ApplyLogFilter equivalence ───────────────────────────────────────

    [Fact]
    public void GroupEvents_AndIncrementalPath_ProduceSameResult()
    {
        var allEvents = new List<RelayEvent>
        {
            Heartbeat(7, "frontier", "msg3"),
            Heartbeat(7, "frontier", "msg2"),
            StageStart(7, "frontier"),
            Heartbeat(7, "frontier", "msg1"),
        };

        // Path 1: GroupEvents directly (simulates ApplyLogFilter rebuild)
        var grouped = RunLogGrouper.GroupEvents(allEvents);

        // Path 2: incremental path (simulates HandleRelayEvent one at a time)
        var incrementalRows = new ObservableCollection<IRunLogRow>();
        foreach (var evt in allEvents)
        {
            if (incrementalRows.Count > 0 && RunLogGrouper.MergeNewest(incrementalRows, evt))
                continue;
            incrementalRows.Insert(0, new SingleEventRow(evt));
        }

        Assert.Equal(grouped.Count, incrementalRows.Count);
        for (var i = 0; i < grouped.Count; i++)
        {
            Assert.Equal(grouped[i].DisplayLine, incrementalRows[i].DisplayLine);
            Assert.Equal(grouped[i].IsGroup, incrementalRows[i].IsGroup);
            Assert.Equal(grouped[i].Count, incrementalRows[i].Count);
        }
    }

    [Fact]
    public void GroupEvents_AndIncrementalPath_WithTierChange_ProduceSameResult()
    {
        var allEvents = new List<RelayEvent>
        {
            Heartbeat(7, "balanced", "b2"),
            Heartbeat(7, "balanced", "b1"),
            Heartbeat(7, "frontier", "f2"),
            Heartbeat(7, "frontier", "f1"),
        };

        var grouped = RunLogGrouper.GroupEvents(allEvents);

        var incrementalRows = new ObservableCollection<IRunLogRow>();
        foreach (var evt in allEvents)
        {
            if (incrementalRows.Count > 0 && RunLogGrouper.MergeNewest(incrementalRows, evt))
                continue;
            incrementalRows.Insert(0, new SingleEventRow(evt));
        }

        Assert.Equal(grouped.Count, incrementalRows.Count);
        for (var i = 0; i < grouped.Count; i++)
        {
            Assert.Equal(grouped[i].DisplayLine, incrementalRows[i].DisplayLine);
            Assert.Equal(grouped[i].IsGroup, incrementalRows[i].IsGroup);
            Assert.Equal(grouped[i].Count, incrementalRows[i].Count);
        }
    }
}

using System.Collections.ObjectModel;
using Avalonia.Controls;
using Avalonia.Threading;
using Avalonia.VisualTree;
using VisualRelay.App.ViewModels;
using VisualRelay.App.ViewModels.RunLogRows;
using VisualRelay.App.Views.Controls;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

[Collection("Headless")]
public sealed class RunLogGroupingRenderTests
{
    /// <summary>
    /// When a <see cref="HeartbeatGroupRow"/> with count &gt; 1 is the data
    /// context, the rendered Run Log shows the count indicator (e.g. "×30") in
    /// the header line.  This test constructs the <see cref="RunLogView"/>
    /// control directly (no <see cref="MainWindow"/> boot) and inspects the
    /// visual tree.
    /// </summary>
    [AvaloniaFact]
    public void GroupedRow_RendersCountInHeader()
    {
        var group = HeartbeatGroupRow.Create(
            MakeHeartbeat(7, "frontier", "silenceMs=30000 deadlineMs=90000"),
            MakeHeartbeat(7, "frontier", "silenceMs=29000 deadlineMs=89000"),
            MakeHeartbeat(7, "frontier", "silenceMs=28000 deadlineMs=88000"),
            MakeHeartbeat(7, "frontier", "silenceMs=27000 deadlineMs=87000"),
            MakeHeartbeat(7, "frontier", "silenceMs=26000 deadlineMs=86000"),
            MakeHeartbeat(7, "frontier", "silenceMs=25000 deadlineMs=85000"),
            MakeHeartbeat(7, "frontier", "silenceMs=24000 deadlineMs=84000"),
            MakeHeartbeat(7, "frontier", "silenceMs=23000 deadlineMs=83000"),
            MakeHeartbeat(7, "frontier", "silenceMs=22000 deadlineMs=82000"),
            MakeHeartbeat(7, "frontier", "silenceMs=21000 deadlineMs=81000"),
            MakeHeartbeat(7, "frontier", "silenceMs=20000 deadlineMs=80000"),
            MakeHeartbeat(7, "frontier", "silenceMs=19000 deadlineMs=79000"),
            MakeHeartbeat(7, "frontier", "silenceMs=18000 deadlineMs=78000"),
            MakeHeartbeat(7, "frontier", "silenceMs=17000 deadlineMs=77000"),
            MakeHeartbeat(7, "frontier", "silenceMs=16000 deadlineMs=76000"),
            MakeHeartbeat(7, "frontier", "silenceMs=15000 deadlineMs=75000"),
            MakeHeartbeat(7, "frontier", "silenceMs=14000 deadlineMs=74000"),
            MakeHeartbeat(7, "frontier", "silenceMs=13000 deadlineMs=73000"),
            MakeHeartbeat(7, "frontier", "silenceMs=12000 deadlineMs=72000"),
            MakeHeartbeat(7, "frontier", "silenceMs=11000 deadlineMs=71000"),
            MakeHeartbeat(7, "frontier", "silenceMs=10000 deadlineMs=70000"),
            MakeHeartbeat(7, "frontier", "silenceMs=9000 deadlineMs=69000"),
            MakeHeartbeat(7, "frontier", "silenceMs=8000 deadlineMs=68000"),
            MakeHeartbeat(7, "frontier", "silenceMs=7000 deadlineMs=67000"),
            MakeHeartbeat(7, "frontier", "silenceMs=6000 deadlineMs=66000"),
            MakeHeartbeat(7, "frontier", "silenceMs=5000 deadlineMs=65000"),
            MakeHeartbeat(7, "frontier", "silenceMs=4000 deadlineMs=64000"),
            MakeHeartbeat(7, "frontier", "silenceMs=3000 deadlineMs=63000"),
            MakeHeartbeat(7, "frontier", "silenceMs=2000 deadlineMs=62000"),
            MakeHeartbeat(7, "frontier", "silenceMs=1000 deadlineMs=61000"),
        );

        Assert.True(group.IsGroup);
        Assert.Equal(30, group.Count);

        var vm = new MainWindowViewModel(
            new DictionaryEnvironmentAccessor { ["XDG_CONFIG_HOME"] = Path.GetTempPath() });
        vm.Events.Add(group);

        var runLogView = new RunLogView { DataContext = vm };
        var host = new Window { Content = runLogView, Width = 600, Height = 400 };
        host.Show();
        Dispatcher.UIThread.RunJobs();

        var allText = runLogView.GetVisualDescendants()
            .OfType<TextBlock>()
            .Where(tb => tb.IsVisible)
            .Select(tb => tb.Text)
            .Concat(runLogView.GetVisualDescendants()
                .OfType<SelectableTextBlock>()
                .Where(stb => stb.IsVisible)
                .Select(stb => stb.Text))
            .ToList();

        // The header must contain the count indicator
        Assert.Contains(allText, t => t != null && t.Contains("×30", StringComparison.Ordinal));

        // The header must also contain the shared display line
        Assert.Contains(allText, t => t != null && t.Contains("s7/frontier watchdog_heartbeat", StringComparison.Ordinal));
    }

    /// <summary>
    /// A non-grouped heartbeat (count = 1) renders without a count indicator
    /// — it looks like a plain single row.
    /// </summary>
    [AvaloniaFact]
    public void SingleHeartbeatRow_RendersWithoutCountIndicator()
    {
        var single = new SingleEventRow(
            MakeHeartbeat(7, "frontier", "silenceMs=1000 deadlineMs=61000"));

        Assert.False(single.IsGroup);
        Assert.Equal(1, single.Count);

        var vm = new MainWindowViewModel(
            new DictionaryEnvironmentAccessor { ["XDG_CONFIG_HOME"] = Path.GetTempPath() });
        vm.Events.Add(single);

        var runLogView = new RunLogView { DataContext = vm };
        var host = new Window { Content = runLogView, Width = 600, Height = 400 };
        host.Show();
        Dispatcher.UIThread.RunJobs();

        var allText = runLogView.GetVisualDescendants()
            .OfType<TextBlock>()
            .Where(tb => tb.IsVisible)
            .Select(tb => tb.Text)
            .Concat(runLogView.GetVisualDescendants()
                .OfType<SelectableTextBlock>()
                .Where(stb => stb.IsVisible)
                .Select(stb => stb.Text))
            .ToList();

        // Must contain the display line
        Assert.Contains(allText, t => t != null && t.Contains("s7/frontier watchdog_heartbeat", StringComparison.Ordinal));

        // Must NOT contain a count indicator (no "×N")
        Assert.DoesNotContain(allText, t => t != null && t.Contains("×", StringComparison.Ordinal));
    }

    /// <summary>
    /// A non-heartbeat event row renders identically to today's single row
    /// — no count, no expander, plain DisplayLine + DetailLine.
    /// </summary>
    [AvaloniaFact]
    public void NonHeartbeatRow_RendersPlainHeader()
    {
        var evt = new RelayEvent(
            DateTimeOffset.UtcNow, "info", "stage_start", "run-1", "/root",
            "task-1", 5, "balanced");
        var row = new SingleEventRow(evt);

        var vm = new MainWindowViewModel(
            new DictionaryEnvironmentAccessor { ["XDG_CONFIG_HOME"] = Path.GetTempPath() });
        vm.Events.Add(row);

        var runLogView = new RunLogView { DataContext = vm };
        var host = new Window { Content = runLogView, Width = 600, Height = 400 };
        host.Show();
        Dispatcher.UIThread.RunJobs();

        var allText = runLogView.GetVisualDescendants()
            .OfType<TextBlock>()
            .Where(tb => tb.IsVisible)
            .Select(tb => tb.Text)
            .Concat(runLogView.GetVisualDescendants()
                .OfType<SelectableTextBlock>()
                .Where(stb => stb.IsVisible)
                .Select(stb => stb.Text))
            .ToList();

        Assert.Contains(allText, t => t != null && t.Contains("s5/balanced stage_start", StringComparison.Ordinal));
        // No count indicator
        Assert.DoesNotContain(allText, t => t != null && t.Contains("×", StringComparison.Ordinal));
    }

    private static RelayEvent MakeHeartbeat(int stageNumber, string tier, string message) =>
        new(
            DateTimeOffset.UtcNow,
            "debug",
            "watchdog_heartbeat",
            "run-1",
            "/root",
            "task-1",
            stageNumber,
            tier,
            Data: new Dictionary<string, string> { ["message"] = message });
}
